final _legacyTemplates = <({RegExp pattern, String id})>[
  (
    pattern: RegExp(
      '^Bundled euddraft 0\\.10\\.2\\.5 \\(editor\\.1\\)\nNo separate Python installation is required\\. Updates are managed with the app\\.\n([\\s\\S]*?)\nLicenses and modification details: BUNDLE-NOTICE\\.txt in this folder\\.\$',
    ),
    id: 'editorBundledEuddraft01025Editor1No',
  ),
  (
    pattern: RegExp(
      '^Move the object inside 0\\.\\.([\\s\\S]*?) by 0\\.\\.([\\s\\S]*?), or keep the raw record unchanged if the value is intentional EUD data\\.\$',
    ),
    id: 'editorMoveTheObjectInside0By0OrKeep',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) pending changes across upgrades and players\\. Apply updates the document; Save As writes the map\\.\$',
    ),
    id: 'editorPendingChangesAcrossUpgradesAndPlayersApplyUpdatesThe',
  ),
  (
    pattern: RegExp(
      '^Copies only current upgrade #([\\s\\S]*?) player edits to Players 1–8\\. Map costs and defaults are excluded\\.\$',
    ),
    id: 'editorCopiesOnlyCurrentUpgradePlayerEditsToPlayers1',
  ),
  (
    pattern: RegExp(
      '^Use left < right and top < bottom inside 0\\.\\.([\\s\\S]*?) by 0\\.\\.([\\s\\S]*?), or preserve the raw value if intentional\\.\$',
    ),
    id: 'editorUseLeftRightAndTopBottomInside0By',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) pending changes across techs and players\\. Apply updates the document; Save As writes the map\\.\$',
    ),
    id: 'editorPendingChangesAcrossTechsAndPlayersApplyUpdatesThe',
  ),
  (
    pattern: RegExp(
      '^Copies only current tech #([\\s\\S]*?) player edits to Players 1–8\\. Map costs and defaults are excluded\\.\$',
    ),
    id: 'editorCopiesOnlyCurrentTechPlayerEditsToPlayers1',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) pending changes\\. Apply updates all edited units and players; Save As writes the map\\.\$',
    ),
    id: 'editorPendingChangesApplyUpdatesAllEditedUnitsAndPlayers',
  ),
  (
    pattern: RegExp(
      '^Copies only current Unit #([\\s\\S]*?) player edits to Players 1–8\\. Map defaults are excluded\\.\$',
    ),
    id: 'editorCopiesOnlyCurrentUnitPlayerEditsToPlayers1',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) pending field changes\\. Apply updates all edited players; Save As writes the map\\.\$',
    ),
    id: 'editorPendingFieldChangesApplyUpdatesAllEditedPlayersSave',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) uses string ID ([\\s\\S]*?), but multiple STR/STRx tables make the reference ambiguous\\.\$',
    ),
    id: 'editorUsesStringIDButMultipleSTRSTRxTablesMake',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) strings • ([\\s\\S]*?) bytes • offset limit ([\\s\\S]*?) • Save As writes pending resource changes\\.\$',
    ),
    id: 'editorStringsBytesOffsetLimitSaveAsWritesPendingResource',
  ),
  (
    pattern: RegExp(
      '^Section "([\\s\\S]*?)" declares ([\\s\\S]*?) strings, but its offset table exceeds the payload\\.\$',
    ),
    id: 'editorSectionDeclaresStringsButItsOffsetTableExceedsThe',
  ),
  (
    pattern: RegExp(
      '^Auto-selected: ([\\s\\S]*?) \\(#([\\s\\S]*?)\\) from ([\\s\\S]*?)\\. Weapon changes affect all units sharing it\\.\$',
    ),
    id: 'editorAutoSelectedFromWeaponChangesAffectAllUnitsSharing',
  ),
  (
    pattern: RegExp(
      '^String ([\\s\\S]*?) in section "([\\s\\S]*?)" has no null terminator before the payload ends\\.\$',
    ),
    id: 'editorStringInSectionHasNoNullTerminatorBeforeThe',
  ),
  (
    pattern: RegExp(
      '^([\\s\\S]*?) action\\(s\\) reference this slot\\. Applying changes affects all of them\\.\$',
    ),
    id: 'editorActionSReferenceThisSlotApplyingChangesAffectsAll',
